window.MG_LAZY_DATA["data/lazy/courses/a027-4a6f72d135aa0179.json"]={sha256:"4a6f72d135aa0179a526d00a3bf433531b86653e51e72fa5df989b6510b5459f",value:{"id":"a027","title":"次二奈米邏輯製程研究","titleEn":"Sub-2-nm logic process research","category":"semiconductor","kind":"course","summary":"以 4 階段、24 個工程工作包拆解比較基準、架構權衡及證據成熟度，完成圖解、對照、敏感度分析、故障判別、量測規劃與驗收。","summaryEn":"Four stages and 24 work packages explore comparison baselines, architecture tradeoffs and evidence maturity through diagrams, comparisons, sensitivity studies, fault diagnosis, measurement plans and acceptance reviews.","sourceIds":["v8a-scaling","v8a-cfet","v8a-backside","v10-video-bf0998107592"],"status":"guided","contentStatus":"reviewable-educational-curriculum","curriculumVersion":8,"depth":4,"stepCount":24,"estimatedMinutes":720,"simulationOnly":true,"languageCoverage":["zh-TW","en"],"scope":"依公開原理編寫的雙語概念實作課；每步交付可審查的工程證據。24 步是學習拆解，不代表晶圓廠的完整配方。自行設定的數值須標為假設。題目不含可直接操作的化學混配、設備設定或量產公差；照片與外部影片為代表媒體，不是假稱每步實拍。","scopeEn":"Bilingual conceptual exercises based on public principles, with reviewable evidence at each step. The 24 steps are a learning decomposition, not a complete fab recipe. Chosen numerical inputs must be labeled hypothetical. No directly operable chemical mixtures, equipment settings or production tolerances are supplied. Photos and external videos are representative media, not claimed as recordings of every step.","diagram":{"type":"wafer","labels":["節點與比較基準","元件及圖案","電源及互連","研究證據"],"labelsEn":["Nodes and comparison baselines","Devices and patterning","Power and interconnects","Research evidence"],"original":true,"notToScale":true},"stages":[{"id":"a027-stage01","order":1,"title":"節點與比較基準","titleEn":"Nodes and comparison baselines","description":"在「節點與比較基準」建立六項互補證據，逐一檢查材料、幾何、物理機制與適用限制。","descriptionEn":"Build six complementary evidence items for nodes and comparison baselines, checking materials, geometry, mechanisms and validity limits.","steps":[{"id":"a027-v8-01","order":1,"sequence":1,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-scaling","v8a-cfet","v8a-backside"],"prerequisiteIds":[],"title":"節點名稱","titleEn":"Interpret node names","objective":"完成「節點名稱」的因果圖，把比較基準、架構權衡及證據成熟度中的相關限制連到可觀察證據。","objectiveEn":"Complete a causal diagram for interpret node names, connecting relevant limits in comparison baselines, architecture tradeoffs and evidence maturity to observable evidence.","instruction":"本步問題：節點名稱。畫一張含作用前後狀態的原創圖；以箭頭標出本步原理中的因果關係；圈出一項仍需量測的未知量。判讀依據：節點名稱不是任何單一實體幾何的直接量測。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Interpret node names. Draw an original before/after diagram; mark the causal relationship in this step; circle one quantity still requiring measurement. Interpretation: A node name is not a direct measurement of one physical dimension. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「節點名稱不是任何單一實體幾何的直接量測。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: A node name is not a direct measurement of one physical dimension. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：總電流合格就證明每個通道都完整。 應回到「節點名稱」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Acceptable total current proves every channel is intact. Revisit assumptions and sampling for interpret node names and add discriminating evidence.","check":"交付「節點名稱」因果圖：圖中要有邊界、輸入、輸出與一項不能僅由圖決定的量。","checkEn":"Submit the causal diagram for interpret node names: Show boundaries, inputs, outputs and one quantity that the diagram alone cannot determine.","knowledge":[{"id":"a027-v8-01-k1","title":"節點名稱的原理","titleEn":"Interpret node names principle","text":"節點名稱不是任何單一實體幾何的直接量測。","textEn":"A node name is not a direct measurement of one physical dimension."},{"id":"a027-v8-01-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"節點比較需要明確 PPA、工作負載及幾何基準，商業名稱與研究預測不可直接充當性能證據。","textEn":"Node comparisons require explicit PPA, workload and geometry baselines; commercial names and projections are not performance evidence."}],"quiz":{"question":"評估「節點名稱」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating interpret node names?","options":["節點名稱不是任何單一實體幾何的直接量測。","總電流合格就證明每個通道都完整。","頂面膜厚代表所有側壁與底部厚度。"],"optionsEn":["A node name is not a direct measurement of one physical dimension.","Acceptable total current proves every channel is intact.","Top thickness represents all sidewall and bottom thicknesses."],"answer":0,"explanation":"節點名稱不是任何單一實體幾何的直接量測。 節點比較需要明確 PPA、工作負載及幾何基準，商業名稱與研究預測不可直接充當性能證據。","explanationEn":"A node name is not a direct measurement of one physical dimension. Node comparisons require explicit PPA, workload and geometry baselines; commercial names and projections are not performance evidence."}},{"id":"a027-v8-02","order":2,"sequence":2,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-scaling","v8a-cfet","v8a-backside"],"prerequisiteIds":["a027-v8-01"],"title":"幾何參數表","titleEn":"Build a geometry table","objective":"完成「幾何參數表」的對照表，把比較基準、架構權衡及證據成熟度中的相關限制連到可觀察證據。","objectiveEn":"Complete a controlled comparison for build a geometry table, connecting relevant limits in comparison baselines, architecture tradeoffs and evidence maturity to observable evidence.","instruction":"本步問題：幾何參數表。建立兩個只改一項條件的假想案例；分開記錄可觀察差異與推測原因；說明如何用本步原理區分兩者。判讀依據：閘長、閘節距、金屬節距與元件高度各自不同。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Build a geometry table. Create two hypothetical cases differing in one condition; separate observations from proposed causes; use this step’s principle to distinguish them. Interpretation: Gate length, gate pitch, metal pitch and cell height are distinct. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「閘長、閘節距、金屬節距與元件高度各自不同。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Gate length, gate pitch, metal pitch and cell height are distinct. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：總電流合格就證明每個通道都完整。 應回到「幾何參數表」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Acceptable total current proves every channel is intact. Revisit assumptions and sampling for build a geometry table and add discriminating evidence.","check":"交付「幾何參數表」對照表：交出兩案例、固定條件、預期差異及一項可能混淆因素。","checkEn":"Submit the controlled comparison for build a geometry table: Submit both cases, fixed conditions, predicted difference and one confounder.","knowledge":[{"id":"a027-v8-02-k1","title":"幾何參數表的原理","titleEn":"Build a geometry table principle","text":"閘長、閘節距、金屬節距與元件高度各自不同。","textEn":"Gate length, gate pitch, metal pitch and cell height are distinct."},{"id":"a027-v8-02-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"節點比較需要明確 PPA、工作負載及幾何基準，商業名稱與研究預測不可直接充當性能證據。","textEn":"Node comparisons require explicit PPA, workload and geometry baselines; commercial names and projections are not performance evidence."}],"quiz":{"question":"評估「幾何參數表」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating build a geometry table?","options":["總電流合格就證明每個通道都完整。","閘長、閘節距、金屬節距與元件高度各自不同。","頂面膜厚代表所有側壁與底部厚度。"],"optionsEn":["Acceptable total current proves every channel is intact.","Gate length, gate pitch, metal pitch and cell height are distinct.","Top thickness represents all sidewall and bottom thicknesses."],"answer":1,"explanation":"閘長、閘節距、金屬節距與元件高度各自不同。 節點比較需要明確 PPA、工作負載及幾何基準，商業名稱與研究預測不可直接充當性能證據。","explanationEn":"Gate length, gate pitch, metal pitch and cell height are distinct. Node comparisons require explicit PPA, workload and geometry baselines; commercial names and projections are not performance evidence."}},{"id":"a027-v8-03","order":3,"sequence":3,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-scaling","v8a-cfet","v8a-backside"],"prerequisiteIds":["a027-v8-02"],"title":"工作負載基準","titleEn":"Choose workload baselines","objective":"完成「工作負載基準」的敏感度草圖，把比較基準、架構權衡及證據成熟度中的相關限制連到可觀察證據。","objectiveEn":"Complete a sensitivity sketch for choose workload baselines, connecting relevant limits in comparison baselines, architecture tradeoffs and evidence maturity to observable evidence.","instruction":"本步問題：工作負載基準。選出本步的一項輸入及一項輸出；以自訂低、中、高三點畫趨勢；逐點標註假設，並寫出趨勢可能失效的條件。判讀依據：效能比較需要相同工作負載與限制條件。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Choose workload baselines. Select one input and output for this step; sketch a hypothetical low/mid/high trend; label assumptions and state when the trend may fail. Interpretation: Performance comparisons require matched workloads and constraints. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「效能比較需要相同工作負載與限制條件。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Performance comparisons require matched workloads and constraints. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：總電流合格就證明每個通道都完整。 應回到「工作負載基準」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Acceptable total current proves every channel is intact. Revisit assumptions and sampling for choose workload baselines and add discriminating evidence.","check":"交付「工作負載基準」敏感度草圖：圖須有變數、單位或無因次定義、三個假設點及適用範圍。","checkEn":"Submit the sensitivity sketch for choose workload baselines: Include variables, units or dimensionless definitions, three hypothetical points and validity limits.","knowledge":[{"id":"a027-v8-03-k1","title":"工作負載基準的原理","titleEn":"Choose workload baselines principle","text":"效能比較需要相同工作負載與限制條件。","textEn":"Performance comparisons require matched workloads and constraints."},{"id":"a027-v8-03-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"節點比較需要明確 PPA、工作負載及幾何基準，商業名稱與研究預測不可直接充當性能證據。","textEn":"Node comparisons require explicit PPA, workload and geometry baselines; commercial names and projections are not performance evidence."}],"quiz":{"question":"評估「工作負載基準」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating choose workload baselines?","options":["總電流合格就證明每個通道都完整。","頂面膜厚代表所有側壁與底部厚度。","效能比較需要相同工作負載與限制條件。"],"optionsEn":["Acceptable total current proves every channel is intact.","Top thickness represents all sidewall and bottom thicknesses.","Performance comparisons require matched workloads and constraints."],"answer":2,"explanation":"效能比較需要相同工作負載與限制條件。 節點比較需要明確 PPA、工作負載及幾何基準，商業名稱與研究預測不可直接充當性能證據。","explanationEn":"Performance comparisons require matched workloads and constraints. Node comparisons require explicit PPA, workload and geometry baselines; commercial names and projections are not performance evidence."}},{"id":"a027-v8-04","order":4,"sequence":4,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-scaling","v8a-cfet","v8a-backside"],"prerequisiteIds":["a027-v8-03"],"title":"功耗效能面積","titleEn":"Separate PPA metrics","objective":"完成「功耗效能面積」的故障判別表，把比較基準、架構權衡及證據成熟度中的相關限制連到可觀察證據。","objectiveEn":"Complete a fault-discrimination table for separate ppa metrics, connecting relevant limits in comparison baselines, architecture tradeoffs and evidence maturity to observable evidence.","instruction":"本步問題：功耗效能面積。假設本步預期結果未出現；提出兩個不同機制；為各機制選一個能支持或否定的觀察，避免只重複同一量測。判讀依據：功耗、效能與面積通常不能同時單獨最佳化。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。 自行建立三個候選架構的正規化 PPA 表，包含一個低功耗但面積較大方案；標明全部是假設，找出 Pareto 不被支配集合而非加總不相容單位。","instructionEn":"Question for this step: Separate PPA metrics. Assume the expected result fails; propose two distinct mechanisms; choose an observation that supports or rejects each rather than repeating one measurement. Interpretation: Power, performance and area generally cannot be independently optimized together. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs. Create hypothetical normalized PPA data for three architectures including a low-power, larger-area option. Identify the nondominated Pareto set rather than adding incompatible units.","observation":"檢查結果是否能支持「功耗、效能與面積通常不能同時單獨最佳化。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Power, performance and area generally cannot be independently optimized together. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：總電流合格就證明每個通道都完整。 應回到「功耗效能面積」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Acceptable total current proves every channel is intact. Revisit assumptions and sampling for separate ppa metrics and add discriminating evidence.","check":"交付「功耗效能面積」故障判別表：至少列出兩個假說、各自的辨別證據及先檢查順序。 同時交付算例的中間步驟或比較圖，並標示假設與模型限制。","checkEn":"Submit the fault-discrimination table for separate ppa metrics: List two hypotheses, discriminating evidence for each and a check order. Also submit intermediate calculations or comparison diagrams with assumptions and model limits.","knowledge":[{"id":"a027-v8-04-k1","title":"功耗效能面積的原理","titleEn":"Separate PPA metrics principle","text":"功耗、效能與面積通常不能同時單獨最佳化。","textEn":"Power, performance and area generally cannot be independently optimized together."},{"id":"a027-v8-04-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"節點比較需要明確 PPA、工作負載及幾何基準，商業名稱與研究預測不可直接充當性能證據。","textEn":"Node comparisons require explicit PPA, workload and geometry baselines; commercial names and projections are not performance evidence."}],"quiz":{"question":"評估「功耗效能面積」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating separate ppa metrics?","options":["功耗、效能與面積通常不能同時單獨最佳化。","總電流合格就證明每個通道都完整。","頂面膜厚代表所有側壁與底部厚度。"],"optionsEn":["Power, performance and area generally cannot be independently optimized together.","Acceptable total current proves every channel is intact.","Top thickness represents all sidewall and bottom thicknesses."],"answer":0,"explanation":"功耗、效能與面積通常不能同時單獨最佳化。 節點比較需要明確 PPA、工作負載及幾何基準，商業名稱與研究預測不可直接充當性能證據。","explanationEn":"Power, performance and area generally cannot be independently optimized together. Node comparisons require explicit PPA, workload and geometry baselines; commercial names and projections are not performance evidence."}},{"id":"a027-v8-05","order":5,"sequence":5,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-scaling","v8a-cfet","v8a-backside"],"prerequisiteIds":["a027-v8-04"],"title":"模型與量測","titleEn":"Classify evidence types","objective":"完成「模型與量測」的量測規劃，把比較基準、架構權衡及證據成熟度中的相關限制連到可觀察證據。","objectiveEn":"Complete a measurement plan for classify evidence types, connecting relevant limits in comparison baselines, architecture tradeoffs and evidence maturity to observable evidence.","instruction":"本步問題：模型與量測。針對本步定義待測量及採樣位置；列出解析度、背景與重複性；設計一個見證或空白，並說明檢出限如何限制結論。判讀依據：模擬預測、單元展示與量產數據不可混稱。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Classify evidence types. Define the measurand and sampling locations; list resolution, background and repeatability; design a witness or blank and explain detection-limit constraints. Interpretation: Predictions, test demonstrations and production data are distinct evidence. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「模擬預測、單元展示與量產數據不可混稱。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Predictions, test demonstrations and production data are distinct evidence. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：總電流合格就證明每個通道都完整。 應回到「模型與量測」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Acceptable total current proves every channel is intact. Revisit assumptions and sampling for classify evidence types and add discriminating evidence.","check":"交付「模型與量測」量測規劃：提供採樣座標、量測單位、對照與不確定度來源。","checkEn":"Submit the measurement plan for classify evidence types: Provide sampling coordinates, units, controls and uncertainty sources.","knowledge":[{"id":"a027-v8-05-k1","title":"模型與量測的原理","titleEn":"Classify evidence types principle","text":"模擬預測、單元展示與量產數據不可混稱。","textEn":"Predictions, test demonstrations and production data are distinct evidence."},{"id":"a027-v8-05-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"節點比較需要明確 PPA、工作負載及幾何基準，商業名稱與研究預測不可直接充當性能證據。","textEn":"Node comparisons require explicit PPA, workload and geometry baselines; commercial names and projections are not performance evidence."}],"quiz":{"question":"評估「模型與量測」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating classify evidence types?","options":["總電流合格就證明每個通道都完整。","模擬預測、單元展示與量產數據不可混稱。","頂面膜厚代表所有側壁與底部厚度。"],"optionsEn":["Acceptable total current proves every channel is intact.","Predictions, test demonstrations and production data are distinct evidence.","Top thickness represents all sidewall and bottom thicknesses."],"answer":1,"explanation":"模擬預測、單元展示與量產數據不可混稱。 節點比較需要明確 PPA、工作負載及幾何基準，商業名稱與研究預測不可直接充當性能證據。","explanationEn":"Predictions, test demonstrations and production data are distinct evidence. Node comparisons require explicit PPA, workload and geometry baselines; commercial names and projections are not performance evidence."}},{"id":"a027-v8-06","order":6,"sequence":6,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-scaling","v8a-cfet","v8a-backside"],"prerequisiteIds":["a027-v8-05"],"title":"不確定度帳本","titleEn":"Create an uncertainty ledger","objective":"完成「不確定度帳本」的工程驗收單，把比較基準、架構權衡及證據成熟度中的相關限制連到可觀察證據。","objectiveEn":"Complete a engineering acceptance sheet for create an uncertainty ledger, connecting relevant limits in comparison baselines, architecture tradeoffs and evidence maturity to observable evidence.","instruction":"本步問題：不確定度帳本。整合本步及本階段先前證據；提出兩項彼此不同的接受條件；再列一個會讓你暫緩放行的結果及下一個確認動作。判讀依據：公開缺失參數須標記未知，不能補成廠商規格。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Create an uncertainty ledger. Combine this step with earlier stage evidence; propose two independent acceptance criteria; name one hold condition and the next confirming action. Interpretation: Missing public parameters remain unknown rather than invented specifications. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「公開缺失參數須標記未知，不能補成廠商規格。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Missing public parameters remain unknown rather than invented specifications. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：總電流合格就證明每個通道都完整。 應回到「不確定度帳本」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Acceptable total current proves every channel is intact. Revisit assumptions and sampling for create an uncertainty ledger and add discriminating evidence.","check":"交付「不確定度帳本」工程驗收單：驗收單需有原理、兩項證據、保留疑問及前後模組交接。","checkEn":"Submit the engineering acceptance sheet for create an uncertainty ledger: The sheet needs the principle, two evidence items, open questions and module handoff.","knowledge":[{"id":"a027-v8-06-k1","title":"不確定度帳本的原理","titleEn":"Create an uncertainty ledger principle","text":"公開缺失參數須標記未知，不能補成廠商規格。","textEn":"Missing public parameters remain unknown rather than invented specifications."},{"id":"a027-v8-06-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"節點比較需要明確 PPA、工作負載及幾何基準，商業名稱與研究預測不可直接充當性能證據。","textEn":"Node comparisons require explicit PPA, workload and geometry baselines; commercial names and projections are not performance evidence."}],"quiz":{"question":"評估「不確定度帳本」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating create an uncertainty ledger?","options":["總電流合格就證明每個通道都完整。","頂面膜厚代表所有側壁與底部厚度。","公開缺失參數須標記未知，不能補成廠商規格。"],"optionsEn":["Acceptable total current proves every channel is intact.","Top thickness represents all sidewall and bottom thicknesses.","Missing public parameters remain unknown rather than invented specifications."],"answer":2,"explanation":"公開缺失參數須標記未知，不能補成廠商規格。 節點比較需要明確 PPA、工作負載及幾何基準，商業名稱與研究預測不可直接充當性能證據。","explanationEn":"Missing public parameters remain unknown rather than invented specifications. Node comparisons require explicit PPA, workload and geometry baselines; commercial names and projections are not performance evidence."}}]},{"id":"a027-stage02","order":2,"title":"元件及圖案","titleEn":"Devices and patterning","description":"在「元件及圖案」建立六項互補證據，逐一檢查材料、幾何、物理機制與適用限制。","descriptionEn":"Build six complementary evidence items for devices and patterning, checking materials, geometry, mechanisms and validity limits.","steps":[{"id":"a027-v8-07","order":1,"sequence":7,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-scaling","v8a-cfet","v8a-backside"],"prerequisiteIds":["a027-v8-06"],"title":"奈米片選項","titleEn":"Compare nanosheet options","objective":"完成「奈米片選項」的因果圖，把比較基準、架構權衡及證據成熟度中的相關限制連到可觀察證據。","objectiveEn":"Complete a causal diagram for compare nanosheet options, connecting relevant limits in comparison baselines, architecture tradeoffs and evidence maturity to observable evidence.","instruction":"本步問題：奈米片選項。畫一張含作用前後狀態的原創圖；以箭頭標出本步原理中的因果關係；圈出一項仍需量測的未知量。判讀依據：寬度可調與堆疊製程限制需一起比較。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Compare nanosheet options. Draw an original before/after diagram; mark the causal relationship in this step; circle one quantity still requiring measurement. Interpretation: Width flexibility must be weighed against stack-processing limits. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「寬度可調與堆疊製程限制需一起比較。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Width flexibility must be weighed against stack-processing limits. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：幾何完整即可省略漏電量測。 應回到「奈米片選項」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Geometric integrity eliminates the need for leakage measurements. Revisit assumptions and sampling for compare nanosheet options and add discriminating evidence.","check":"交付「奈米片選項」因果圖：圖中要有邊界、輸入、輸出與一項不能僅由圖決定的量。","checkEn":"Submit the causal diagram for compare nanosheet options: Show boundaries, inputs, outputs and one quantity that the diagram alone cannot determine.","knowledge":[{"id":"a027-v8-07-k1","title":"奈米片選項的原理","titleEn":"Compare nanosheet options principle","text":"寬度可調與堆疊製程限制需一起比較。","textEn":"Width flexibility must be weighed against stack-processing limits."},{"id":"a027-v8-07-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"架構改變會同時影響靜電、電容與加工可達性，單項通道指標的改善不等於整合方案更優。","textEn":"Architecture changes electrostatics, capacitance and process access; improving one channel metric does not prove a better integrated solution."}],"quiz":{"question":"評估「奈米片選項」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating compare nanosheet options?","options":["寬度可調與堆疊製程限制需一起比較。","幾何完整即可省略漏電量測。","接觸面積加倍必定使全部串聯電阻減半。"],"optionsEn":["Width flexibility must be weighed against stack-processing limits.","Geometric integrity eliminates the need for leakage measurements.","Doubling contact area must halve all series resistance."],"answer":0,"explanation":"寬度可調與堆疊製程限制需一起比較。 架構改變會同時影響靜電、電容與加工可達性，單項通道指標的改善不等於整合方案更優。","explanationEn":"Width flexibility must be weighed against stack-processing limits. Architecture changes electrostatics, capacitance and process access; improving one channel metric does not prove a better integrated solution."}},{"id":"a027-v8-08","order":2,"sequence":8,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-scaling","v8a-cfet","v8a-backside"],"prerequisiteIds":["a027-v8-07"],"title":"Forksheet 選項","titleEn":"Assess forksheet options","objective":"完成「Forksheet 選項」的對照表，把比較基準、架構權衡及證據成熟度中的相關限制連到可觀察證據。","objectiveEn":"Complete a controlled comparison for assess forksheet options, connecting relevant limits in comparison baselines, architecture tradeoffs and evidence maturity to observable evidence.","instruction":"本步問題：Forksheet 選項。建立兩個只改一項條件的假想案例；分開記錄可觀察差異與推測原因；說明如何用本步原理區分兩者。判讀依據：介電牆改變 n-p 間距與閘加工空間。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Assess forksheet options. Create two hypothetical cases differing in one condition; separate observations from proposed causes; use this step’s principle to distinguish them. Interpretation: A dielectric wall changes n-p separation and gate-processing space. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「介電牆改變 n-p 間距與閘加工空間。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: A dielectric wall changes n-p separation and gate-processing space. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：幾何完整即可省略漏電量測。 應回到「Forksheet 選項」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Geometric integrity eliminates the need for leakage measurements. Revisit assumptions and sampling for assess forksheet options and add discriminating evidence.","check":"交付「Forksheet 選項」對照表：交出兩案例、固定條件、預期差異及一項可能混淆因素。","checkEn":"Submit the controlled comparison for assess forksheet options: Submit both cases, fixed conditions, predicted difference and one confounder.","knowledge":[{"id":"a027-v8-08-k1","title":"Forksheet 選項的原理","titleEn":"Assess forksheet options principle","text":"介電牆改變 n-p 間距與閘加工空間。","textEn":"A dielectric wall changes n-p separation and gate-processing space."},{"id":"a027-v8-08-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"架構改變會同時影響靜電、電容與加工可達性，單項通道指標的改善不等於整合方案更優。","textEn":"Architecture changes electrostatics, capacitance and process access; improving one channel metric does not prove a better integrated solution."}],"quiz":{"question":"評估「Forksheet 選項」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating assess forksheet options?","options":["幾何完整即可省略漏電量測。","介電牆改變 n-p 間距與閘加工空間。","接觸面積加倍必定使全部串聯電阻減半。"],"optionsEn":["Geometric integrity eliminates the need for leakage measurements.","A dielectric wall changes n-p separation and gate-processing space.","Doubling contact area must halve all series resistance."],"answer":1,"explanation":"介電牆改變 n-p 間距與閘加工空間。 架構改變會同時影響靜電、電容與加工可達性，單項通道指標的改善不等於整合方案更優。","explanationEn":"A dielectric wall changes n-p separation and gate-processing space. Architecture changes electrostatics, capacitance and process access; improving one channel metric does not prove a better integrated solution."}},{"id":"a027-v8-09","order":3,"sequence":9,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-scaling","v8a-cfet","v8a-backside"],"prerequisiteIds":["a027-v8-08"],"title":"CFET 選項","titleEn":"Assess CFET options","objective":"完成「CFET 選項」的敏感度草圖，把比較基準、架構權衡及證據成熟度中的相關限制連到可觀察證據。","objectiveEn":"Complete a sensitivity sketch for assess cfet options, connecting relevant limits in comparison baselines, architecture tradeoffs and evidence maturity to observable evidence.","instruction":"本步問題：CFET 選項。選出本步的一項輸入及一項輸出；以自訂低、中、高三點畫趨勢；逐點標註假設，並寫出趨勢可能失效的條件。判讀依據：垂直互補可省平面面積但增加上下接觸難題。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Assess CFET options. Select one input and output for this step; sketch a hypothetical low/mid/high trend; label assumptions and state when the trend may fail. Interpretation: Vertical complementarity saves lateral area but complicates tier contacts. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「垂直互補可省平面面積但增加上下接觸難題。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Vertical complementarity saves lateral area but complicates tier contacts. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：幾何完整即可省略漏電量測。 應回到「CFET 選項」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Geometric integrity eliminates the need for leakage measurements. Revisit assumptions and sampling for assess cfet options and add discriminating evidence.","check":"交付「CFET 選項」敏感度草圖：圖須有變數、單位或無因次定義、三個假設點及適用範圍。","checkEn":"Submit the sensitivity sketch for assess cfet options: Include variables, units or dimensionless definitions, three hypothetical points and validity limits.","knowledge":[{"id":"a027-v8-09-k1","title":"CFET 選項的原理","titleEn":"Assess CFET options principle","text":"垂直互補可省平面面積但增加上下接觸難題。","textEn":"Vertical complementarity saves lateral area but complicates tier contacts."},{"id":"a027-v8-09-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"架構改變會同時影響靜電、電容與加工可達性，單項通道指標的改善不等於整合方案更優。","textEn":"Architecture changes electrostatics, capacitance and process access; improving one channel metric does not prove a better integrated solution."}],"quiz":{"question":"評估「CFET 選項」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating assess cfet options?","options":["幾何完整即可省略漏電量測。","接觸面積加倍必定使全部串聯電阻減半。","垂直互補可省平面面積但增加上下接觸難題。"],"optionsEn":["Geometric integrity eliminates the need for leakage measurements.","Doubling contact area must halve all series resistance.","Vertical complementarity saves lateral area but complicates tier contacts."],"answer":2,"explanation":"垂直互補可省平面面積但增加上下接觸難題。 架構改變會同時影響靜電、電容與加工可達性，單項通道指標的改善不等於整合方案更優。","explanationEn":"Vertical complementarity saves lateral area but complicates tier contacts. Architecture changes electrostatics, capacitance and process access; improving one channel metric does not prove a better integrated solution."}},{"id":"a027-v8-10","order":4,"sequence":10,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-scaling","v8a-cfet","v8a-backside"],"prerequisiteIds":["a027-v8-09"],"title":"通道材料","titleEn":"Compare channel materials","objective":"完成「通道材料」的故障判別表，把比較基準、架構權衡及證據成熟度中的相關限制連到可觀察證據。","objectiveEn":"Complete a fault-discrimination table for compare channel materials, connecting relevant limits in comparison baselines, architecture tradeoffs and evidence maturity to observable evidence.","instruction":"本步問題：通道材料。假設本步預期結果未出現；提出兩個不同機制；為各機制選一個能支持或否定的觀察，避免只重複同一量測。判讀依據：高遷移率材料仍需可用介面與接觸。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Compare channel materials. Assume the expected result fails; propose two distinct mechanisms; choose an observation that supports or rejects each rather than repeating one measurement. Interpretation: High-mobility materials still require workable interfaces and contacts. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「高遷移率材料仍需可用介面與接觸。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: High-mobility materials still require workable interfaces and contacts. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：幾何完整即可省略漏電量測。 應回到「通道材料」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Geometric integrity eliminates the need for leakage measurements. Revisit assumptions and sampling for compare channel materials and add discriminating evidence.","check":"交付「通道材料」故障判別表：至少列出兩個假說、各自的辨別證據及先檢查順序。","checkEn":"Submit the fault-discrimination table for compare channel materials: List two hypotheses, discriminating evidence for each and a check order.","knowledge":[{"id":"a027-v8-10-k1","title":"通道材料的原理","titleEn":"Compare channel materials principle","text":"高遷移率材料仍需可用介面與接觸。","textEn":"High-mobility materials still require workable interfaces and contacts."},{"id":"a027-v8-10-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"架構改變會同時影響靜電、電容與加工可達性，單項通道指標的改善不等於整合方案更優。","textEn":"Architecture changes electrostatics, capacitance and process access; improving one channel metric does not prove a better integrated solution."}],"quiz":{"question":"評估「通道材料」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating compare channel materials?","options":["高遷移率材料仍需可用介面與接觸。","幾何完整即可省略漏電量測。","接觸面積加倍必定使全部串聯電阻減半。"],"optionsEn":["High-mobility materials still require workable interfaces and contacts.","Geometric integrity eliminates the need for leakage measurements.","Doubling contact area must halve all series resistance."],"answer":0,"explanation":"高遷移率材料仍需可用介面與接觸。 架構改變會同時影響靜電、電容與加工可達性，單項通道指標的改善不等於整合方案更優。","explanationEn":"High-mobility materials still require workable interfaces and contacts. Architecture changes electrostatics, capacitance and process access; improving one channel metric does not prove a better integrated solution."}},{"id":"a027-v8-11","order":5,"sequence":11,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-scaling","v8a-cfet","v8a-backside"],"prerequisiteIds":["a027-v8-10"],"title":"圖案化分解","titleEn":"Decompose patterning needs","objective":"完成「圖案化分解」的量測規劃，把比較基準、架構權衡及證據成熟度中的相關限制連到可觀察證據。","objectiveEn":"Complete a measurement plan for decompose patterning needs, connecting relevant limits in comparison baselines, architecture tradeoffs and evidence maturity to observable evidence.","instruction":"本步問題：圖案化分解。針對本步定義待測量及採樣位置；列出解析度、背景與重複性；設計一個見證或空白，並說明檢出限如何限制結論。判讀依據：曝光解析度、套刻及缺陷率是不同限制。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Decompose patterning needs. Define the measurand and sampling locations; list resolution, background and repeatability; design a witness or blank and explain detection-limit constraints. Interpretation: Resolution, overlay and defectivity are distinct patterning limits. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「曝光解析度、套刻及缺陷率是不同限制。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Resolution, overlay and defectivity are distinct patterning limits. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：幾何完整即可省略漏電量測。 應回到「圖案化分解」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Geometric integrity eliminates the need for leakage measurements. Revisit assumptions and sampling for decompose patterning needs and add discriminating evidence.","check":"交付「圖案化分解」量測規劃：提供採樣座標、量測單位、對照與不確定度來源。","checkEn":"Submit the measurement plan for decompose patterning needs: Provide sampling coordinates, units, controls and uncertainty sources.","knowledge":[{"id":"a027-v8-11-k1","title":"圖案化分解的原理","titleEn":"Decompose patterning needs principle","text":"曝光解析度、套刻及缺陷率是不同限制。","textEn":"Resolution, overlay and defectivity are distinct patterning limits."},{"id":"a027-v8-11-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"架構改變會同時影響靜電、電容與加工可達性，單項通道指標的改善不等於整合方案更優。","textEn":"Architecture changes electrostatics, capacitance and process access; improving one channel metric does not prove a better integrated solution."}],"quiz":{"question":"評估「圖案化分解」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating decompose patterning needs?","options":["幾何完整即可省略漏電量測。","曝光解析度、套刻及缺陷率是不同限制。","接觸面積加倍必定使全部串聯電阻減半。"],"optionsEn":["Geometric integrity eliminates the need for leakage measurements.","Resolution, overlay and defectivity are distinct patterning limits.","Doubling contact area must halve all series resistance."],"answer":1,"explanation":"曝光解析度、套刻及缺陷率是不同限制。 架構改變會同時影響靜電、電容與加工可達性，單項通道指標的改善不等於整合方案更優。","explanationEn":"Resolution, overlay and defectivity are distinct patterning limits. Architecture changes electrostatics, capacitance and process access; improving one channel metric does not prove a better integrated solution."}},{"id":"a027-v8-12","order":6,"sequence":12,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-scaling","v8a-cfet","v8a-backside"],"prerequisiteIds":["a027-v8-11"],"title":"High-NA 邊界","titleEn":"Assess High-NA boundaries","objective":"完成「High-NA 邊界」的工程驗收單，把比較基準、架構權衡及證據成熟度中的相關限制連到可觀察證據。","objectiveEn":"Complete a engineering acceptance sheet for assess high-na boundaries, connecting relevant limits in comparison baselines, architecture tradeoffs and evidence maturity to observable evidence.","instruction":"本步問題：High-NA 邊界。整合本步及本階段先前證據；提出兩項彼此不同的接受條件；再列一個會讓你暫緩放行的結果及下一個確認動作。判讀依據：高數值孔徑改變成像條件但不自動解決全部整合。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Assess High-NA boundaries. Combine this step with earlier stage evidence; propose two independent acceptance criteria; name one hold condition and the next confirming action. Interpretation: Higher numerical aperture changes imaging but does not solve all integration issues. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「高數值孔徑改變成像條件但不自動解決全部整合。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Higher numerical aperture changes imaging but does not solve all integration issues. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：幾何完整即可省略漏電量測。 應回到「High-NA 邊界」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Geometric integrity eliminates the need for leakage measurements. Revisit assumptions and sampling for assess high-na boundaries and add discriminating evidence.","check":"交付「High-NA 邊界」工程驗收單：驗收單需有原理、兩項證據、保留疑問及前後模組交接。","checkEn":"Submit the engineering acceptance sheet for assess high-na boundaries: The sheet needs the principle, two evidence items, open questions and module handoff.","knowledge":[{"id":"a027-v8-12-k1","title":"High-NA 邊界的原理","titleEn":"Assess High-NA boundaries principle","text":"高數值孔徑改變成像條件但不自動解決全部整合。","textEn":"Higher numerical aperture changes imaging but does not solve all integration issues."},{"id":"a027-v8-12-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"架構改變會同時影響靜電、電容與加工可達性，單項通道指標的改善不等於整合方案更優。","textEn":"Architecture changes electrostatics, capacitance and process access; improving one channel metric does not prove a better integrated solution."}],"quiz":{"question":"評估「High-NA 邊界」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating assess high-na boundaries?","options":["幾何完整即可省略漏電量測。","接觸面積加倍必定使全部串聯電阻減半。","高數值孔徑改變成像條件但不自動解決全部整合。"],"optionsEn":["Geometric integrity eliminates the need for leakage measurements.","Doubling contact area must halve all series resistance.","Higher numerical aperture changes imaging but does not solve all integration issues."],"answer":2,"explanation":"高數值孔徑改變成像條件但不自動解決全部整合。 架構改變會同時影響靜電、電容與加工可達性，單項通道指標的改善不等於整合方案更優。","explanationEn":"Higher numerical aperture changes imaging but does not solve all integration issues. Architecture changes electrostatics, capacitance and process access; improving one channel metric does not prove a better integrated solution."}}]},{"id":"a027-stage03","order":3,"title":"電源及互連","titleEn":"Power and interconnects","description":"在「電源及互連」建立六項互補證據，逐一檢查材料、幾何、物理機制與適用限制。","descriptionEn":"Build six complementary evidence items for power and interconnects, checking materials, geometry, mechanisms and validity limits.","steps":[{"id":"a027-v8-13","order":1,"sequence":13,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-scaling","v8a-cfet","v8a-backside"],"prerequisiteIds":["a027-v8-12"],"title":"接觸瓶頸","titleEn":"Locate contact bottlenecks","objective":"完成「接觸瓶頸」的因果圖，把比較基準、架構權衡及證據成熟度中的相關限制連到可觀察證據。","objectiveEn":"Complete a causal diagram for locate contact bottlenecks, connecting relevant limits in comparison baselines, architecture tradeoffs and evidence maturity to observable evidence.","instruction":"本步問題：接觸瓶頸。畫一張含作用前後狀態的原創圖；以箭頭標出本步原理中的因果關係；圈出一項仍需量測的未知量。判讀依據：通道改善可能被增加的存取電阻抵銷。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Locate contact bottlenecks. Draw an original before/after diagram; mark the causal relationship in this step; circle one quantity still requiring measurement. Interpretation: Channel improvements can be offset by access resistance. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「通道改善可能被增加的存取電阻抵銷。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Channel improvements can be offset by access resistance. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：節點名稱就是實體閘長的量測值。 應回到「接觸瓶頸」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: The node name is a measured physical gate length. Revisit assumptions and sampling for locate contact bottlenecks and add discriminating evidence.","check":"交付「接觸瓶頸」因果圖：圖中要有邊界、輸入、輸出與一項不能僅由圖決定的量。","checkEn":"Submit the causal diagram for locate contact bottlenecks: Show boundaries, inputs, outputs and one quantity that the diagram alone cannot determine.","knowledge":[{"id":"a027-v8-13-k1","title":"接觸瓶頸的原理","titleEn":"Locate contact bottlenecks principle","text":"通道改善可能被增加的存取電阻抵銷。","textEn":"Channel improvements can be offset by access resistance."},{"id":"a027-v8-13-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"當接觸與互連占比增加，通道縮放對電路效能的改善可能遞減，需要由元件跨到配線協同設計。","textEn":"As contacts and interconnects contribute more, channel-scaling gains can diminish, requiring device-routing co-design."}],"quiz":{"question":"評估「接觸瓶頸」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating locate contact bottlenecks?","options":["通道改善可能被增加的存取電阻抵銷。","節點名稱就是實體閘長的量測值。","模擬最佳值可直接當成量產良率。"],"optionsEn":["Channel improvements can be offset by access resistance.","The node name is a measured physical gate length.","The best simulation value directly represents production yield."],"answer":0,"explanation":"通道改善可能被增加的存取電阻抵銷。 當接觸與互連占比增加，通道縮放對電路效能的改善可能遞減，需要由元件跨到配線協同設計。","explanationEn":"Channel improvements can be offset by access resistance. As contacts and interconnects contribute more, channel-scaling gains can diminish, requiring device-routing co-design."}},{"id":"a027-v8-14","order":2,"sequence":14,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-scaling","v8a-cfet","v8a-backside"],"prerequisiteIds":["a027-v8-13"],"title":"局部配線材料","titleEn":"Compare local interconnect materials","objective":"完成「局部配線材料」的對照表，把比較基準、架構權衡及證據成熟度中的相關限制連到可觀察證據。","objectiveEn":"Complete a controlled comparison for compare local interconnect materials, connecting relevant limits in comparison baselines, architecture tradeoffs and evidence maturity to observable evidence.","instruction":"本步問題：局部配線材料。建立兩個只改一項條件的假想案例；分開記錄可觀察差異與推測原因；說明如何用本步原理區分兩者。判讀依據：窄線電阻不可只套用塊材電阻率。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Compare local interconnect materials. Create two hypothetical cases differing in one condition; separate observations from proposed causes; use this step’s principle to distinguish them. Interpretation: Narrow-line resistance cannot be inferred from bulk resistivity alone. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「窄線電阻不可只套用塊材電阻率。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Narrow-line resistance cannot be inferred from bulk resistivity alone. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：節點名稱就是實體閘長的量測值。 應回到「局部配線材料」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: The node name is a measured physical gate length. Revisit assumptions and sampling for compare local interconnect materials and add discriminating evidence.","check":"交付「局部配線材料」對照表：交出兩案例、固定條件、預期差異及一項可能混淆因素。","checkEn":"Submit the controlled comparison for compare local interconnect materials: Submit both cases, fixed conditions, predicted difference and one confounder.","knowledge":[{"id":"a027-v8-14-k1","title":"局部配線材料的原理","titleEn":"Compare local interconnect materials principle","text":"窄線電阻不可只套用塊材電阻率。","textEn":"Narrow-line resistance cannot be inferred from bulk resistivity alone."},{"id":"a027-v8-14-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"當接觸與互連占比增加，通道縮放對電路效能的改善可能遞減，需要由元件跨到配線協同設計。","textEn":"As contacts and interconnects contribute more, channel-scaling gains can diminish, requiring device-routing co-design."}],"quiz":{"question":"評估「局部配線材料」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating compare local interconnect materials?","options":["節點名稱就是實體閘長的量測值。","窄線電阻不可只套用塊材電阻率。","模擬最佳值可直接當成量產良率。"],"optionsEn":["The node name is a measured physical gate length.","Narrow-line resistance cannot be inferred from bulk resistivity alone.","The best simulation value directly represents production yield."],"answer":1,"explanation":"窄線電阻不可只套用塊材電阻率。 當接觸與互連占比增加，通道縮放對電路效能的改善可能遞減，需要由元件跨到配線協同設計。","explanationEn":"Narrow-line resistance cannot be inferred from bulk resistivity alone. As contacts and interconnects contribute more, channel-scaling gains can diminish, requiring device-routing co-design."}},{"id":"a027-v8-15","order":3,"sequence":15,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-scaling","v8a-cfet","v8a-backside"],"prerequisiteIds":["a027-v8-14"],"title":"背面供電","titleEn":"Assess backside power","objective":"完成「背面供電」的敏感度草圖，把比較基準、架構權衡及證據成熟度中的相關限制連到可觀察證據。","objectiveEn":"Complete a sensitivity sketch for assess backside power, connecting relevant limits in comparison baselines, architecture tradeoffs and evidence maturity to observable evidence.","instruction":"本步問題：背面供電。選出本步的一項輸入及一項輸出；以自訂低、中、高三點畫趨勢；逐點標註假設，並寫出趨勢可能失效的條件。判讀依據：正背面分工可減少擁塞但增加薄化及接觸模組。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Assess backside power. Select one input and output for this step; sketch a hypothetical low/mid/high trend; label assumptions and state when the trend may fail. Interpretation: Front-back separation can reduce congestion but adds thinning and contacts. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「正背面分工可減少擁塞但增加薄化及接觸模組。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Front-back separation can reduce congestion but adds thinning and contacts. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：節點名稱就是實體閘長的量測值。 應回到「背面供電」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: The node name is a measured physical gate length. Revisit assumptions and sampling for assess backside power and add discriminating evidence.","check":"交付「背面供電」敏感度草圖：圖須有變數、單位或無因次定義、三個假設點及適用範圍。","checkEn":"Submit the sensitivity sketch for assess backside power: Include variables, units or dimensionless definitions, three hypothetical points and validity limits.","knowledge":[{"id":"a027-v8-15-k1","title":"背面供電的原理","titleEn":"Assess backside power principle","text":"正背面分工可減少擁塞但增加薄化及接觸模組。","textEn":"Front-back separation can reduce congestion but adds thinning and contacts."},{"id":"a027-v8-15-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"當接觸與互連占比增加，通道縮放對電路效能的改善可能遞減，需要由元件跨到配線協同設計。","textEn":"As contacts and interconnects contribute more, channel-scaling gains can diminish, requiring device-routing co-design."}],"quiz":{"question":"評估「背面供電」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating assess backside power?","options":["節點名稱就是實體閘長的量測值。","模擬最佳值可直接當成量產良率。","正背面分工可減少擁塞但增加薄化及接觸模組。"],"optionsEn":["The node name is a measured physical gate length.","The best simulation value directly represents production yield.","Front-back separation can reduce congestion but adds thinning and contacts."],"answer":2,"explanation":"正背面分工可減少擁塞但增加薄化及接觸模組。 當接觸與互連占比增加，通道縮放對電路效能的改善可能遞減，需要由元件跨到配線協同設計。","explanationEn":"Front-back separation can reduce congestion but adds thinning and contacts. As contacts and interconnects contribute more, channel-scaling gains can diminish, requiring device-routing co-design."}},{"id":"a027-v8-16","order":4,"sequence":16,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-scaling","v8a-cfet","v8a-backside"],"prerequisiteIds":["a027-v8-15"],"title":"熱路徑","titleEn":"Budget thermal pathways","objective":"完成「熱路徑」的故障判別表，把比較基準、架構權衡及證據成熟度中的相關限制連到可觀察證據。","objectiveEn":"Complete a fault-discrimination table for budget thermal pathways, connecting relevant limits in comparison baselines, architecture tradeoffs and evidence maturity to observable evidence.","instruction":"本步問題：熱路徑。假設本步預期結果未出現；提出兩個不同機制；為各機制選一個能支持或否定的觀察，避免只重複同一量測。判讀依據：高密度與垂直堆疊會改變局部熱阻。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Budget thermal pathways. Assume the expected result fails; propose two distinct mechanisms; choose an observation that supports or rejects each rather than repeating one measurement. Interpretation: Density and vertical stacking change local thermal resistance. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「高密度與垂直堆疊會改變局部熱阻。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Density and vertical stacking change local thermal resistance. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：節點名稱就是實體閘長的量測值。 應回到「熱路徑」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: The node name is a measured physical gate length. Revisit assumptions and sampling for budget thermal pathways and add discriminating evidence.","check":"交付「熱路徑」故障判別表：至少列出兩個假說、各自的辨別證據及先檢查順序。","checkEn":"Submit the fault-discrimination table for budget thermal pathways: List two hypotheses, discriminating evidence for each and a check order.","knowledge":[{"id":"a027-v8-16-k1","title":"熱路徑的原理","titleEn":"Budget thermal pathways principle","text":"高密度與垂直堆疊會改變局部熱阻。","textEn":"Density and vertical stacking change local thermal resistance."},{"id":"a027-v8-16-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"當接觸與互連占比增加，通道縮放對電路效能的改善可能遞減，需要由元件跨到配線協同設計。","textEn":"As contacts and interconnects contribute more, channel-scaling gains can diminish, requiring device-routing co-design."}],"quiz":{"question":"評估「熱路徑」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating budget thermal pathways?","options":["高密度與垂直堆疊會改變局部熱阻。","節點名稱就是實體閘長的量測值。","模擬最佳值可直接當成量產良率。"],"optionsEn":["Density and vertical stacking change local thermal resistance.","The node name is a measured physical gate length.","The best simulation value directly represents production yield."],"answer":0,"explanation":"高密度與垂直堆疊會改變局部熱阻。 當接觸與互連占比增加，通道縮放對電路效能的改善可能遞減，需要由元件跨到配線協同設計。","explanationEn":"Density and vertical stacking change local thermal resistance. As contacts and interconnects contribute more, channel-scaling gains can diminish, requiring device-routing co-design."}},{"id":"a027-v8-17","order":5,"sequence":17,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-scaling","v8a-cfet","v8a-backside"],"prerequisiteIds":["a027-v8-16"],"title":"標準元件協同","titleEn":"Co-design standard cells","objective":"完成「標準元件協同」的量測規劃，把比較基準、架構權衡及證據成熟度中的相關限制連到可觀察證據。","objectiveEn":"Complete a measurement plan for co-design standard cells, connecting relevant limits in comparison baselines, architecture tradeoffs and evidence maturity to observable evidence.","instruction":"本步問題：標準元件協同。針對本步定義待測量及採樣位置；列出解析度、背景與重複性；設計一個見證或空白，並說明檢出限如何限制結論。判讀依據：元件截面需與可實際連線的元件庫一起評估。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Co-design standard cells. Define the measurand and sampling locations; list resolution, background and repeatability; design a witness or blank and explain detection-limit constraints. Interpretation: Device sections need evaluation with routable cell libraries. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「元件截面需與可實際連線的元件庫一起評估。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Device sections need evaluation with routable cell libraries. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：節點名稱就是實體閘長的量測值。 應回到「標準元件協同」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: The node name is a measured physical gate length. Revisit assumptions and sampling for co-design standard cells and add discriminating evidence.","check":"交付「標準元件協同」量測規劃：提供採樣座標、量測單位、對照與不確定度來源。","checkEn":"Submit the measurement plan for co-design standard cells: Provide sampling coordinates, units, controls and uncertainty sources.","knowledge":[{"id":"a027-v8-17-k1","title":"標準元件協同的原理","titleEn":"Co-design standard cells principle","text":"元件截面需與可實際連線的元件庫一起評估。","textEn":"Device sections need evaluation with routable cell libraries."},{"id":"a027-v8-17-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"當接觸與互連占比增加，通道縮放對電路效能的改善可能遞減，需要由元件跨到配線協同設計。","textEn":"As contacts and interconnects contribute more, channel-scaling gains can diminish, requiring device-routing co-design."}],"quiz":{"question":"評估「標準元件協同」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating co-design standard cells?","options":["節點名稱就是實體閘長的量測值。","元件截面需與可實際連線的元件庫一起評估。","模擬最佳值可直接當成量產良率。"],"optionsEn":["The node name is a measured physical gate length.","Device sections need evaluation with routable cell libraries.","The best simulation value directly represents production yield."],"answer":1,"explanation":"元件截面需與可實際連線的元件庫一起評估。 當接觸與互連占比增加，通道縮放對電路效能的改善可能遞減，需要由元件跨到配線協同設計。","explanationEn":"Device sections need evaluation with routable cell libraries. As contacts and interconnects contribute more, channel-scaling gains can diminish, requiring device-routing co-design."}},{"id":"a027-v8-18","order":6,"sequence":18,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-scaling","v8a-cfet","v8a-backside"],"prerequisiteIds":["a027-v8-17"],"title":"SRAM 不同需求","titleEn":"Separate SRAM constraints","objective":"完成「SRAM 不同需求」的工程驗收單，把比較基準、架構權衡及證據成熟度中的相關限制連到可觀察證據。","objectiveEn":"Complete a engineering acceptance sheet for separate sram constraints, connecting relevant limits in comparison baselines, architecture tradeoffs and evidence maturity to observable evidence.","instruction":"本步問題：SRAM 不同需求。整合本步及本階段先前證據；提出兩項彼此不同的接受條件；再列一個會讓你暫緩放行的結果及下一個確認動作。判讀依據：記憶體單元的穩定裕度不同於單純邏輯延遲。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Separate SRAM constraints. Combine this step with earlier stage evidence; propose two independent acceptance criteria; name one hold condition and the next confirming action. Interpretation: Memory-cell stability differs from logic-delay optimization. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「記憶體單元的穩定裕度不同於單純邏輯延遲。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Memory-cell stability differs from logic-delay optimization. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：節點名稱就是實體閘長的量測值。 應回到「SRAM 不同需求」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: The node name is a measured physical gate length. Revisit assumptions and sampling for separate sram constraints and add discriminating evidence.","check":"交付「SRAM 不同需求」工程驗收單：驗收單需有原理、兩項證據、保留疑問及前後模組交接。","checkEn":"Submit the engineering acceptance sheet for separate sram constraints: The sheet needs the principle, two evidence items, open questions and module handoff.","knowledge":[{"id":"a027-v8-18-k1","title":"SRAM 不同需求的原理","titleEn":"Separate SRAM constraints principle","text":"記憶體單元的穩定裕度不同於單純邏輯延遲。","textEn":"Memory-cell stability differs from logic-delay optimization."},{"id":"a027-v8-18-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"當接觸與互連占比增加，通道縮放對電路效能的改善可能遞減，需要由元件跨到配線協同設計。","textEn":"As contacts and interconnects contribute more, channel-scaling gains can diminish, requiring device-routing co-design."}],"quiz":{"question":"評估「SRAM 不同需求」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating separate sram constraints?","options":["節點名稱就是實體閘長的量測值。","模擬最佳值可直接當成量產良率。","記憶體單元的穩定裕度不同於單純邏輯延遲。"],"optionsEn":["The node name is a measured physical gate length.","The best simulation value directly represents production yield.","Memory-cell stability differs from logic-delay optimization."],"answer":2,"explanation":"記憶體單元的穩定裕度不同於單純邏輯延遲。 當接觸與互連占比增加，通道縮放對電路效能的改善可能遞減，需要由元件跨到配線協同設計。","explanationEn":"Memory-cell stability differs from logic-delay optimization. As contacts and interconnects contribute more, channel-scaling gains can diminish, requiring device-routing co-design."}}]},{"id":"a027-stage04","order":4,"title":"研究證據","titleEn":"Research evidence","description":"在「研究證據」建立六項互補證據，逐一檢查材料、幾何、物理機制與適用限制。","descriptionEn":"Build six complementary evidence items for research evidence, checking materials, geometry, mechanisms and validity limits.","steps":[{"id":"a027-v8-19","order":1,"sequence":19,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-scaling","v8a-cfet","v8a-backside"],"prerequisiteIds":["a027-v8-18"],"title":"變異來源","titleEn":"Build a variability budget","objective":"完成「變異來源」的因果圖，把比較基準、架構權衡及證據成熟度中的相關限制連到可觀察證據。","objectiveEn":"Complete a causal diagram for build a variability budget, connecting relevant limits in comparison baselines, architecture tradeoffs and evidence maturity to observable evidence.","instruction":"本步問題：變異來源。畫一張含作用前後狀態的原創圖；以箭頭標出本步原理中的因果關係；圈出一項仍需量測的未知量。判讀依據：幾何、材料與隨機缺陷需分開估算。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Build a variability budget. Draw an original before/after diagram; mark the causal relationship in this step; circle one quantity still requiring measurement. Interpretation: Geometry, materials and stochastic defects need separate estimates. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「幾何、材料與隨機缺陷需分開估算。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Geometry, materials and stochastic defects need separate estimates. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：單一中層截面可代表所有堆疊層。 應回到「變異來源」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: One middle-layer section represents every stacked layer. Revisit assumptions and sampling for build a variability budget and add discriminating evidence.","check":"交付「變異來源」因果圖：圖中要有邊界、輸入、輸出與一項不能僅由圖決定的量。","checkEn":"Submit the causal diagram for build a variability budget: Show boundaries, inputs, outputs and one quantity that the diagram alone cannot determine.","knowledge":[{"id":"a027-v8-19-k1","title":"變異來源的原理","titleEn":"Build a variability budget principle","text":"幾何、材料與隨機缺陷需分開估算。","textEn":"Geometry, materials and stochastic defects need separate estimates."},{"id":"a027-v8-19-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"模擬、測試結構與量產資料的抽樣範圍不同，研究結論應附樣本、偏壓、模型假設及可重現條件。","textEn":"Simulations, test structures and production data sample different scopes; state samples, bias, model assumptions and reproducibility conditions."}],"quiz":{"question":"評估「變異來源」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating build a variability budget?","options":["幾何、材料與隨機缺陷需分開估算。","單一中層截面可代表所有堆疊層。","低電阻可自動證明介電隔離完整。"],"optionsEn":["Geometry, materials and stochastic defects need separate estimates.","One middle-layer section represents every stacked layer.","Low resistance automatically proves dielectric isolation."],"answer":0,"explanation":"幾何、材料與隨機缺陷需分開估算。 模擬、測試結構與量產資料的抽樣範圍不同，研究結論應附樣本、偏壓、模型假設及可重現條件。","explanationEn":"Geometry, materials and stochastic defects need separate estimates. Simulations, test structures and production data sample different scopes; state samples, bias, model assumptions and reproducibility conditions."}},{"id":"a027-v8-20","order":2,"sequence":20,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-scaling","v8a-cfet","v8a-backside"],"prerequisiteIds":["a027-v8-19"],"title":"可靠度範圍","titleEn":"Define reliability conditions","objective":"完成「可靠度範圍」的對照表，把比較基準、架構權衡及證據成熟度中的相關限制連到可觀察證據。","objectiveEn":"Complete a controlled comparison for define reliability conditions, connecting relevant limits in comparison baselines, architecture tradeoffs and evidence maturity to observable evidence.","instruction":"本步問題：可靠度範圍。建立兩個只改一項條件的假想案例；分開記錄可觀察差異與推測原因；說明如何用本步原理區分兩者。判讀依據：加速壓力試驗須有可解釋的外推模型。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Define reliability conditions. Create two hypothetical cases differing in one condition; separate observations from proposed causes; use this step’s principle to distinguish them. Interpretation: Accelerated stress tests need an interpretable extrapolation model. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「加速壓力試驗須有可解釋的外推模型。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Accelerated stress tests need an interpretable extrapolation model. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：單一中層截面可代表所有堆疊層。 應回到「可靠度範圍」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: One middle-layer section represents every stacked layer. Revisit assumptions and sampling for define reliability conditions and add discriminating evidence.","check":"交付「可靠度範圍」對照表：交出兩案例、固定條件、預期差異及一項可能混淆因素。","checkEn":"Submit the controlled comparison for define reliability conditions: Submit both cases, fixed conditions, predicted difference and one confounder.","knowledge":[{"id":"a027-v8-20-k1","title":"可靠度範圍的原理","titleEn":"Define reliability conditions principle","text":"加速壓力試驗須有可解釋的外推模型。","textEn":"Accelerated stress tests need an interpretable extrapolation model."},{"id":"a027-v8-20-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"模擬、測試結構與量產資料的抽樣範圍不同，研究結論應附樣本、偏壓、模型假設及可重現條件。","textEn":"Simulations, test structures and production data sample different scopes; state samples, bias, model assumptions and reproducibility conditions."}],"quiz":{"question":"評估「可靠度範圍」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating define reliability conditions?","options":["單一中層截面可代表所有堆疊層。","加速壓力試驗須有可解釋的外推模型。","低電阻可自動證明介電隔離完整。"],"optionsEn":["One middle-layer section represents every stacked layer.","Accelerated stress tests need an interpretable extrapolation model.","Low resistance automatically proves dielectric isolation."],"answer":1,"explanation":"加速壓力試驗須有可解釋的外推模型。 模擬、測試結構與量產資料的抽樣範圍不同，研究結論應附樣本、偏壓、模型假設及可重現條件。","explanationEn":"Accelerated stress tests need an interpretable extrapolation model. Simulations, test structures and production data sample different scopes; state samples, bias, model assumptions and reproducibility conditions."}},{"id":"a027-v8-21","order":3,"sequence":21,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-scaling","v8a-cfet","v8a-backside"],"prerequisiteIds":["a027-v8-20"],"title":"良率與成本","titleEn":"Connect yield and cost","objective":"完成「良率與成本」的敏感度草圖，把比較基準、架構權衡及證據成熟度中的相關限制連到可觀察證據。","objectiveEn":"Complete a sensitivity sketch for connect yield and cost, connecting relevant limits in comparison baselines, architecture tradeoffs and evidence maturity to observable evidence.","instruction":"本步問題：良率與成本。選出本步的一項輸入及一項輸出；以自訂低、中、高三點畫趨勢；逐點標註假設，並寫出趨勢可能失效的條件。判讀依據：較小裸晶不保證每顆良品成本較低。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Connect yield and cost. Select one input and output for this step; sketch a hypothetical low/mid/high trend; label assumptions and state when the trend may fail. Interpretation: Smaller dies do not guarantee lower cost per good die. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「較小裸晶不保證每顆良品成本較低。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Smaller dies do not guarantee lower cost per good die. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：單一中層截面可代表所有堆疊層。 應回到「良率與成本」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: One middle-layer section represents every stacked layer. Revisit assumptions and sampling for connect yield and cost and add discriminating evidence.","check":"交付「良率與成本」敏感度草圖：圖須有變數、單位或無因次定義、三個假設點及適用範圍。","checkEn":"Submit the sensitivity sketch for connect yield and cost: Include variables, units or dimensionless definitions, three hypothetical points and validity limits.","knowledge":[{"id":"a027-v8-21-k1","title":"良率與成本的原理","titleEn":"Connect yield and cost principle","text":"較小裸晶不保證每顆良品成本較低。","textEn":"Smaller dies do not guarantee lower cost per good die."},{"id":"a027-v8-21-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"模擬、測試結構與量產資料的抽樣範圍不同，研究結論應附樣本、偏壓、模型假設及可重現條件。","textEn":"Simulations, test structures and production data sample different scopes; state samples, bias, model assumptions and reproducibility conditions."}],"quiz":{"question":"評估「良率與成本」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating connect yield and cost?","options":["單一中層截面可代表所有堆疊層。","低電阻可自動證明介電隔離完整。","較小裸晶不保證每顆良品成本較低。"],"optionsEn":["One middle-layer section represents every stacked layer.","Low resistance automatically proves dielectric isolation.","Smaller dies do not guarantee lower cost per good die."],"answer":2,"explanation":"較小裸晶不保證每顆良品成本較低。 模擬、測試結構與量產資料的抽樣範圍不同，研究結論應附樣本、偏壓、模型假設及可重現條件。","explanationEn":"Smaller dies do not guarantee lower cost per good die. Simulations, test structures and production data sample different scopes; state samples, bias, model assumptions and reproducibility conditions."}},{"id":"a027-v8-22","order":4,"sequence":22,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-scaling","v8a-cfet","v8a-backside"],"prerequisiteIds":["a027-v8-21"],"title":"路線圖日期","titleEn":"Version roadmap claims","objective":"完成「路線圖日期」的故障判別表，把比較基準、架構權衡及證據成熟度中的相關限制連到可觀察證據。","objectiveEn":"Complete a fault-discrimination table for version roadmap claims, connecting relevant limits in comparison baselines, architecture tradeoffs and evidence maturity to observable evidence.","instruction":"本步問題：路線圖日期。假設本步預期結果未出現；提出兩個不同機制；為各機制選一個能支持或否定的觀察，避免只重複同一量測。判讀依據：研究路線圖是有日期的預測而非交貨承諾。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Version roadmap claims. Assume the expected result fails; propose two distinct mechanisms; choose an observation that supports or rejects each rather than repeating one measurement. Interpretation: Roadmaps are dated projections rather than delivery commitments. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「研究路線圖是有日期的預測而非交貨承諾。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Roadmaps are dated projections rather than delivery commitments. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：單一中層截面可代表所有堆疊層。 應回到「路線圖日期」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: One middle-layer section represents every stacked layer. Revisit assumptions and sampling for version roadmap claims and add discriminating evidence.","check":"交付「路線圖日期」故障判別表：至少列出兩個假說、各自的辨別證據及先檢查順序。","checkEn":"Submit the fault-discrimination table for version roadmap claims: List two hypotheses, discriminating evidence for each and a check order.","knowledge":[{"id":"a027-v8-22-k1","title":"路線圖日期的原理","titleEn":"Version roadmap claims principle","text":"研究路線圖是有日期的預測而非交貨承諾。","textEn":"Roadmaps are dated projections rather than delivery commitments."},{"id":"a027-v8-22-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"模擬、測試結構與量產資料的抽樣範圍不同，研究結論應附樣本、偏壓、模型假設及可重現條件。","textEn":"Simulations, test structures and production data sample different scopes; state samples, bias, model assumptions and reproducibility conditions."}],"quiz":{"question":"評估「路線圖日期」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating version roadmap claims?","options":["研究路線圖是有日期的預測而非交貨承諾。","單一中層截面可代表所有堆疊層。","低電阻可自動證明介電隔離完整。"],"optionsEn":["Roadmaps are dated projections rather than delivery commitments.","One middle-layer section represents every stacked layer.","Low resistance automatically proves dielectric isolation."],"answer":0,"explanation":"研究路線圖是有日期的預測而非交貨承諾。 模擬、測試結構與量產資料的抽樣範圍不同，研究結論應附樣本、偏壓、模型假設及可重現條件。","explanationEn":"Roadmaps are dated projections rather than delivery commitments. Simulations, test structures and production data sample different scopes; state samples, bias, model assumptions and reproducibility conditions."}},{"id":"a027-v8-23","order":5,"sequence":23,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-scaling","v8a-cfet","v8a-backside"],"prerequisiteIds":["a027-v8-22"],"title":"公平比較矩陣","titleEn":"Build a fair comparison matrix","objective":"完成「公平比較矩陣」的量測規劃，把比較基準、架構權衡及證據成熟度中的相關限制連到可觀察證據。","objectiveEn":"Complete a measurement plan for build a fair comparison matrix, connecting relevant limits in comparison baselines, architecture tradeoffs and evidence maturity to observable evidence.","instruction":"本步問題：公平比較矩陣。針對本步定義待測量及採樣位置；列出解析度、背景與重複性；設計一個見證或空白，並說明檢出限如何限制結論。判讀依據：只選各方案最佳單點會掩蓋共同限制。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Build a fair comparison matrix. Define the measurand and sampling locations; list resolution, background and repeatability; design a witness or blank and explain detection-limit constraints. Interpretation: Selecting each option's best isolated metric hides common constraints. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「只選各方案最佳單點會掩蓋共同限制。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Selecting each option's best isolated metric hides common constraints. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：單一中層截面可代表所有堆疊層。 應回到「公平比較矩陣」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: One middle-layer section represents every stacked layer. Revisit assumptions and sampling for build a fair comparison matrix and add discriminating evidence.","check":"交付「公平比較矩陣」量測規劃：提供採樣座標、量測單位、對照與不確定度來源。","checkEn":"Submit the measurement plan for build a fair comparison matrix: Provide sampling coordinates, units, controls and uncertainty sources.","knowledge":[{"id":"a027-v8-23-k1","title":"公平比較矩陣的原理","titleEn":"Build a fair comparison matrix principle","text":"只選各方案最佳單點會掩蓋共同限制。","textEn":"Selecting each option's best isolated metric hides common constraints."},{"id":"a027-v8-23-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"模擬、測試結構與量產資料的抽樣範圍不同，研究結論應附樣本、偏壓、模型假設及可重現條件。","textEn":"Simulations, test structures and production data sample different scopes; state samples, bias, model assumptions and reproducibility conditions."}],"quiz":{"question":"評估「公平比較矩陣」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating build a fair comparison matrix?","options":["單一中層截面可代表所有堆疊層。","只選各方案最佳單點會掩蓋共同限制。","低電阻可自動證明介電隔離完整。"],"optionsEn":["One middle-layer section represents every stacked layer.","Selecting each option's best isolated metric hides common constraints.","Low resistance automatically proves dielectric isolation."],"answer":1,"explanation":"只選各方案最佳單點會掩蓋共同限制。 模擬、測試結構與量產資料的抽樣範圍不同，研究結論應附樣本、偏壓、模型假設及可重現條件。","explanationEn":"Selecting each option's best isolated metric hides common constraints. Simulations, test structures and production data sample different scopes; state samples, bias, model assumptions and reproducibility conditions."}},{"id":"a027-v8-24","order":6,"sequence":24,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-scaling","v8a-cfet","v8a-backside"],"prerequisiteIds":["a027-v8-23"],"title":"研究提案交付","titleEn":"Deliver a research proposal","objective":"完成「研究提案交付」的工程驗收單，把比較基準、架構權衡及證據成熟度中的相關限制連到可觀察證據。","objectiveEn":"Complete a engineering acceptance sheet for deliver a research proposal, connecting relevant limits in comparison baselines, architecture tradeoffs and evidence maturity to observable evidence.","instruction":"本步問題：研究提案交付。整合本步及本階段先前證據；提出兩項彼此不同的接受條件；再列一個會讓你暫緩放行的結果及下一個確認動作。判讀依據：提出可量測假說、對照組及失敗判準才可檢驗。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Deliver a research proposal. Combine this step with earlier stage evidence; propose two independent acceptance criteria; name one hold condition and the next confirming action. Interpretation: A testable proposal needs measurable hypotheses, controls and failure criteria. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「提出可量測假說、對照組及失敗判準才可檢驗。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: A testable proposal needs measurable hypotheses, controls and failure criteria. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：單一中層截面可代表所有堆疊層。 應回到「研究提案交付」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: One middle-layer section represents every stacked layer. Revisit assumptions and sampling for deliver a research proposal and add discriminating evidence.","check":"交付「研究提案交付」工程驗收單：驗收單需有原理、兩項證據、保留疑問及前後模組交接。","checkEn":"Submit the engineering acceptance sheet for deliver a research proposal: The sheet needs the principle, two evidence items, open questions and module handoff.","knowledge":[{"id":"a027-v8-24-k1","title":"研究提案交付的原理","titleEn":"Deliver a research proposal principle","text":"提出可量測假說、對照組及失敗判準才可檢驗。","textEn":"A testable proposal needs measurable hypotheses, controls and failure criteria."},{"id":"a027-v8-24-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"模擬、測試結構與量產資料的抽樣範圍不同，研究結論應附樣本、偏壓、模型假設及可重現條件。","textEn":"Simulations, test structures and production data sample different scopes; state samples, bias, model assumptions and reproducibility conditions."}],"quiz":{"question":"評估「研究提案交付」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating deliver a research proposal?","options":["單一中層截面可代表所有堆疊層。","低電阻可自動證明介電隔離完整。","提出可量測假說、對照組及失敗判準才可檢驗。"],"optionsEn":["One middle-layer section represents every stacked layer.","Low resistance automatically proves dielectric isolation.","A testable proposal needs measurable hypotheses, controls and failure criteria."],"answer":2,"explanation":"提出可量測假說、對照組及失敗判準才可檢驗。 模擬、測試結構與量產資料的抽樣範圍不同，研究結論應附樣本、偏壓、模型假設及可重現條件。","explanationEn":"A testable proposal needs measurable hypotheses, controls and failure criteria. Simulations, test structures and production data sample different scopes; state samples, bias, model assumptions and reproducibility conditions."}}]}],"subcategory":"devices","subcategoryTitle":"先進電晶體","subcategoryTitleEn":"Advanced transistors"}};
